  'sec.pilotage.intro' => 'Yönetim, bir üst yönetimin baktığı sayıları toplar: kadro, ciro, tahsil edilmemiş faturalar, hedefler ve yaklaşan vadeler. Hiçbir şeyi yeniden hesaplamaz; diğer bölümlerin zaten tuttuğunu bir araya getirir.',
  'sec.personnel.intro' => 'Personel insanları tutar: dosyalar, sözleşmeler, izinler, çizelge, kariyer yolları, sağlık ve güvenlik. Verisi en hassas olan ve en sık kullanılan bölümdür.',
