  'sec.conformite.intro' => 'Uyum, sizden istenenleri tutar: hesap güvenliği, KVKK ve GDPR, şirketler hukuku ve imzalar. Denetim günü açılan bölümdür.',
  'sec.reglages.intro' => 'Ayarlar örneği tutar: şirket kimliği, dil, görünüm, modüller ve uygulamalar. Bu bölüm kaldırılmaz; diğerlerini geri koymayı sağlayan odur.',
